      'import { readFile } from \'fs\';\n\nfunction greet(name: string): string {\n    return `Hello, \${name}!`;\n}\n',
      config: config,
    );
    expect(result.language.toString(), equals('typescript'.toString()));
    expect(result.structure.length, greaterThanOrEqualTo(1));
    expect(
      result.structure.any(
        (e) => e.kind.runtimeType.toString().contains('Function'),
      ),
      isTrue,
    );
    expect(result.imports.length, greaterThanOrEqualTo(1));
    expect(result.metrics.totalLines, greaterThanOrEqualTo(5));
    expect(result.metrics.errorCount, equals(0));
  });
}
